                    <div class="vbar-fill vbar-fill--blue" :style="{ height: barH(point.count, maxSignups) + '%' }"></div>
                  </div>
                </div>
                <div class="vbar-x">
                  <span
                    v-for="(point, i) in signupsChart"
                    :key="'sx' + i"
                    class="vbar-x-lbl"
                  >{{ i % 6 === 0 ? shortDate(point.date) : '' }}</span>
                </div>
              </div>
