                    <th>Attempted</th>
                    <th>Confirmed / Failed</th>
                    <th>Status</th>
                    <th>Amount</th>
                    <th>Method</th>
                    <th>Gateway</th>
                    <th>Phone</th>
                    <th>Reference</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="row in f.recent_payments" :key="row.id">
                    <td class="td-muted">{{ row.id }}</td>
