<script>
import devApi from '../../utils/devApi'
import DeveloperWallet from '../../components/dev/DeveloperWallet.vue'

export default {
  name: 'DevDashboard',
  components: { DeveloperWallet },
  data() {
    const d = new Date()
    return {
      activeSection: 'overview',
      loading: true,
      error: '',
      analytics: null,
      walletSummary: null,
      supportInsights: null,
      supportDays: 30,
      supportLoading: false,
      supportError: '',
      gatewayConfig: { activeProvider: 'jpesa', providers: {} },
      gatewayLoading: false,
      gatewayError: '',
      gatewayTesting: '',
      gatewaySwitching: '',
      retryingCommission: {},
      todayDate: d.toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
      navItems: [
        {
          id: 'overview',
          label: 'Overview',
          desc: 'System snapshot',
          icon: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/></svg>'
        },
        {
          id: 'finance',
          label: 'Finance',
          desc: 'Revenue breakdown',
          icon: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg>'
        },
        {
          id: 'commission',
          label: 'Commission',
          desc: 'Platform transfer tracking',
          icon: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg>'
        },
        {
          id: 'wallet',
          label: 'Wallet & Payouts',
          desc: 'Reserved Relworx commission',
          icon: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 7V5a2 2 0 00-2-2H5a3 3 0 000 6h15v10H5a3 3 0 010-6h15"/><circle cx="16" cy="14" r="1"/></svg>'
        },
        {
          id: 'users',
          label: 'Users',
          desc: 'Member analytics',
          icon: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg>'
        },
        {
          id: 'subscriptions',
          label: 'Packages',
          desc: 'Active plans',
          icon: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>'
        },
        {
          id: 'support',
          label: 'Support Insights',
          desc: 'Customer feedback',
          icon: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a4 4 0 01-4 4H8l-5 3V7a4 4 0 014-4h10a4 4 0 014 4z"/><path d="M8 9h8M8 13h5"/></svg>'
        },
        {
          id: 'gateway',
          label: 'Payment Gateway',
          desc: 'Live routing control',
          icon: '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20M7 15h2"/></svg>'
        }
      ]
    }
  },
  computed: {
    currentSection() {
      return this.navItems.find(n => n.id === this.activeSection) || {}
    },
    f() { return this.analytics?.finance || {} },
    a() { return this.analytics?.finance?.audit || {} },
    c() { return this.analytics?.commission || {} },
    auditHealthy() {
      return Number(this.a.status_count_difference || 0) === 0
        && Number(this.a.status_amount_difference || 0) === 0
        && Number(this.a.confirmed_missing_timestamp_count || 0) === 0
    },
    currentCommission() {
      const available = this.c.available ?? this.c.current_total
      const legacyAvailable = available !== undefined && available !== null
        ? Number(available) || 0
        : Math.max(0, Number(this.c.total_paid || 0) - Number(this.c.total_withdrawn || 0))
      const relworxAvailable = Number(this.walletSummary?.wallet?.by_provider?.relworx?.available || 0)
      return legacyAvailable + relworxAvailable
    },
    u() { return this.analytics?.users || {} },
    s() { return this.analytics?.subscriptions || {} },
    si() { return this.supportInsights || {} },
    gatewayActiveName() {
      return this.gatewayConfig.providers?.[this.gatewayConfig.activeProvider]?.name || 'JPesa'
    },
    supportCategoryRows() {
      return Object.entries(this.si.by_category || {})
        .map(([category, row]) => ({ category, ...row }))
        .filter(row => Number(row.count) > 0)
        .sort((a, b) => Number(b.count) - Number(a.count))
    },
    maxSupportCategory() {
      return Math.max(...this.supportCategoryRows.map(row => Number(row.count) || 0), 1)
    },
    supportTrend() { return this.si.trend || [] },
    maxSupportTrend() {
      return Math.max(...this.supportTrend.map(row => Number(row.conversations) || 0), 1)
    },
    supportTrendLabelStep() {
      if (this.supportTrend.length > 120) return 60
      if (this.supportTrend.length > 60) return 15
      if (this.supportTrend.length > 30) return 10
      return 5
    },
    revenueChart() { return this.analytics?.charts?.revenue || [] },
    signupsChart() { return this.analytics?.charts?.signups || [] },
    maxRevenue() {
      return Math.max(...this.revenueChart.map(d => Number(d.amount) || 0), 1)
    },
    maxSignups() {
      return Math.max(...this.signupsChart.map(d => Number(d.count) || 0), 1)
    },
    maxPlanRevenue() {
      return Math.max(...Object.values(this.f.by_plan || {}).map(Number), 1)
    },
    maxMethodRevenue() {
      return Math.max(...Object.values(this.f.by_method || {}).map(Number), 1)
    },
    maxProviderRevenue() {
      return Math.max(...Object.values(this.f.by_provider || {}).map(row => Number(row.amount) || 0), 1)
    },
    maxPlanComm() {
      return Math.max(...Object.values(this.c.by_plan || {}).map(Number), 1)
    },
    maxMethodComm() {
      return Math.max(...Object.values(this.c.by_method || {}).map(Number), 1)
    },
    maxActivePlan() {
      return Math.max(...Object.values(this.s.active_by_plan || {}).map(Number), 1)
    }
  },
  async mounted() {
    await Promise.all([this.fetchAnalytics(), this.fetchGatewayConfig(), this.fetchWalletSummary()])
  },
  methods: {
    async fetchWalletSummary() {
      try {
        const { data } = await devApi.get('/api/developer/wallet')
        this.walletSummary = data
      } catch { /* The wallet section provides its own retry state. */ }
    },
    async fetchGatewayConfig() {
      this.gatewayLoading = true
      this.gatewayError = ''
      try {
        const { data } = await devApi.get('/api/developer/payment-gateway')
        this.gatewayConfig = data
      } catch (err) {
        this.gatewayError = err.response?.data?.message || 'Payment gateway configuration could not be loaded.'
      } finally {
        this.gatewayLoading = false
      }
    },
    async testGateway(provider) {
      this.gatewayTesting = provider
      this.gatewayError = ''
      try {
        const { data } = await devApi.post(`/api/developer/payment-gateway/${provider}/check`)
        this.gatewayConfig.providers[provider] = {
          ...this.gatewayConfig.providers[provider],
          ...data
        }
      } catch (err) {
        const data = err.response?.data || {}
        if (this.gatewayConfig.providers[provider]) {
          this.gatewayConfig.providers[provider] = {
            ...this.gatewayConfig.providers[provider],
            ...(data.readiness || data),
            ready: false
          }
        }
        this.gatewayError = data.message || 'Gateway connection test failed.'
      } finally {
        this.gatewayTesting = ''
      }
    },
    async switchGateway(provider, name) {
      if (!confirm(`Switch new payment attempts to ${name}? Existing attempts will stay with their original gateway.`)) return
      this.gatewaySwitching = provider
      this.gatewayError = ''
      try {
        const { data } = await devApi.patch('/api/developer/payment-gateway', { provider })
        this.gatewayConfig = data
      } catch (err) {
        this.gatewayError = err.response?.data?.message || `Could not switch to ${name}.`
      } finally {
        this.gatewaySwitching = ''
      }
    },
    async fetchAnalytics() {
      this.loading = true
      this.error = ''
      try {
        const { data } = await devApi.get('/api/analytics/developer')
        this.analytics = data
        await this.fetchSupportInsights()
      } catch (err) {
        if (err.response?.status === 401 || err.response?.status === 403) {
          this.$router.push('/dev/login')
        } else {
          this.error = 'Failed to load analytics data. Please try again.'
        }
      } finally {
        this.loading = false
      }
    },
    async fetchSupportInsights() {
      this.supportLoading = true
      this.supportError = ''
      try {
        const { data } = await devApi.get('/api/analytics/developer/support-insights', {
          params: { days: this.supportDays }
        })
        this.supportInsights = data
      } catch (err) {
        if (err.response?.status === 401 || err.response?.status === 403) {
          this.$router.push('/dev/login')
        } else {
          this.supportError = 'Support insights could not be loaded. Please try again.'
        }
      } finally {
        this.supportLoading = false
      }
    },
    async setSupportDays(days) {
      if (this.supportDays === days || this.supportLoading) return
      this.supportDays = days
      await this.fetchSupportInsights()
    },
    logout() {
      localStorage.removeItem('devToken')
      this.$router.push('/dev/login')
    },
    formatUGX(n) {
      return Number(n || 0).toLocaleString() + ' UGX'
    },
    formatNum(n) {
      return Number(n || 0).toLocaleString()
    },
    barH(value, max) {
      if (!max) return 1
      return Math.max((Number(value) / Number(max)) * 100, 1).toFixed(1)
    },
    hBarW(value, max) {
      if (!max) return 1
      return Math.max((Number(value) / Number(max)) * 100, 1).toFixed(1)
    },
    shortDate(d) {
      if (!d) return ''
      const dt = new Date(d)
      return `${dt.getDate()}/${dt.getMonth() + 1}`
    },
    fmtDate(d) {
      if (!d) return '—'
      return new Date(d).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: '2-digit' })
    },
    fmtDateTime(d) {
      if (!d) return '—'
      return new Date(d).toLocaleString('en-GB', {
        day: '2-digit', month: 'short', year: '2-digit', hour: '2-digit', minute: '2-digit'
      })
    },
    capitalize(s) {
      if (!s) return '—'
      return s.charAt(0).toUpperCase() + s.slice(1)
    },
    statusClass(status) {
      const map = {
        completed:  'st-done',
        processing: 'st-proc',
        pending:    'st-pend',
        failed:     'st-fail'
      }
      return map[status] || 'st-none'
    },
    paymentStatusClass(status) {
      const map = {
        confirmed: 'st-done',
        pending: 'st-pend',
        failed: 'st-fail'
      }
      return map[String(status || '').toLowerCase()] || 'st-none'
    },
    statusLabel(status) {
      const map = {
        completed:  'Paid',
        processing: 'In Progress',
        pending:    'Pending',
        failed:     'Failed'
      }
      return map[status] || (status ? status : 'Queued')
    },
    canRetryCommission(row) {
      if (!this.c.enabled || !row) return false
      const status = String(row.agent_commission_status || '').toLowerCase()
      return status === 'failed' || status === 'pending'
    },
    commissionRetryTitle(row) {
      if (row?.agent_commission_error) {
        return 'Retry commission payment: ' + row.agent_commission_error
      }
      return 'Retry commission payment'
    },
    async retryCommission(row) {
      if (!this.canRetryCommission(row) || this.retryingCommission[row.id]) return
      if (!confirm('Retry commission payment for payment #' + row.id + '?')) return

      this.retryingCommission = { ...this.retryingCommission, [row.id]: true }
      try {
        const { data } = await devApi.post('/api/analytics/developer/payments/' + row.id + '/retry-commission')
        await this.fetchAnalytics()

        if (data && data.success === false) {
          alert(data.message || 'Commission retry did not complete.')
        }
      } catch (err) {
        const message = err.response?.data?.message
          || err.response?.data?.error
          || 'Commission retry failed. Please try again.'
        alert(message)
      } finally {
        this.retryingCommission = { ...this.retryingCommission, [row.id]: false }
      }
    }
  }
}
